// GENERATED by source/build.mjs from source/script.js, viewer.js, ui.js: change those and build again.

// ---- script.js ----

// Reading a generator script: which of a model's files is one, and how its parameters become controls.
//
// Nothing here parses OpenSCAD. The parameter list comes from OpenSCAD itself through the SDK, which is the
// whole point: the groups, ranges, captions and choices are the ones the script's author wrote, read by the
// program that will run the script, not by a guess at its comment syntax.

export const SCRIPT_EXTENSION = ".scad";

/**
 * A script as the engine should see it: Unix line endings.
 *
 * OpenSCAD reads a parameter's widget out of the comment after it, and a trailing CR makes it miss every one --
 * a script written on Windows opens with none of its dropdowns or sliders and nothing to say why. Thingport
 * does this to the scripts it imports, but a file opened from a disk here hasn't been through that.
 */
export function readyScript(text) {
  return text.replace(/\r\n/g, "\n");
}

/** The files of a model that are generator scripts. */
export function scriptsAmong(relatedFiles) {
  return relatedFiles.filter((file) => file.name.toLowerCase().endsWith(SCRIPT_EXTENSION));
}

/**
 * What kind of control a parameter wants.
 *
 * OpenSCAD types a parameter by the value it was declared with, and says separately whether the declaration
 * ended in a list of choices or a range. Those two decide the control: a handful of choices is a set of
 * buttons, a long list is a dropdown, a number with both ends is a slider, and everything else is a field.
 */
export function controlFor(parameter) {
  const options = parameter.options ?? [];
  if (options.length) {
    const yesNo = options.length === 2 && options.every((o) => /^(yes|no|true|false|on|off)$/i.test(String(o.value)));
    if (yesNo) return { kind: "switch", options };
    return options.length <= 4 ? { kind: "segmented", options } : { kind: "select", options };
  }
  if (parameter.type === "boolean") return { kind: "switch", options: BOOLEAN_OPTIONS };
  if (parameter.type === "number") {
    const { min, max } = parameter;
    if (Number.isFinite(min) && Number.isFinite(max)) {
      return { kind: "slider", min, max, step: parameter.step || stepFor(min, max) };
    }
    return { kind: "number", step: parameter.step || 1 };
  }
  if (parameter.type === "vector") return { kind: "vector" };
  return { kind: "text" };
}

const BOOLEAN_OPTIONS = [
  { name: "true", value: true },
  { name: "false", value: false },
];

/** A step fine enough to reach the values in between, without a slider of ten thousand positions. */
function stepFor(min, max) {
  const span = Math.abs(max - min);
  if (span <= 2) return 0.01;
  if (span <= 20) return 0.1;
  return 1;
}

/** Parameters in the order the script declares them, grouped by their `/* [Heading] *\/`. */
export function groupParameters(parameters) {
  const groups = [];
  for (const parameter of parameters) {
    // OpenSCAD's own convention: a group named "Hidden" is the script's workings, not the reader's business.
    if (/^hidden$/i.test(parameter.group)) continue;
    let group = groups.find((g) => g.name === parameter.group);
    if (!group) {
      group = { name: parameter.group, parameters: [] };
      groups.push(group);
    }
    group.parameters.push(parameter);
  }
  return groups;
}

/** The values a script starts on, which are the ones its author chose. */
export function defaultValues(parameters) {
  return Object.fromEntries(parameters.map((parameter) => [parameter.name, parameter.initial]));
}

/** Only what the reader actually moved, so the script's own defaults keep working if it is updated. */
export function changedValues(parameters, values) {
  const changed = {};
  for (const parameter of parameters) {
    const value = values[parameter.name];
    if (value === undefined) continue;
    if (JSON.stringify(value) === JSON.stringify(parameter.initial)) continue;
    changed[parameter.name] = value;
  }
  return changed;
}

/** A filename for the generated model: the script's name, and what was changed, where that is short enough. */
export function generatedName(scriptName, modelName, values) {
  const base = (modelName || scriptName.replace(/\.scad$/i, "")).trim() || "model";
  const text = Object.values(values).find(
    (value) => typeof value === "string" && /\S/.test(value) && value.length < 24,
  );
  return text ? `${base} - ${text}` : base;
}

/** A warning the engine printed that the reader can do something about; the rest is progress chatter. */
export function readableWarnings(log) {
  const seen = new Set();
  const out = [];
  for (const line of log) {
    if (!/^(WARNING|ERROR):/i.test(line)) continue;
    // Said once per use of the font, which for a nameplate is once per letter.
    const text = line.replace(/\s+in file .*$/, "").trim();
    if (seen.has(text)) continue;
    seen.add(text);
    out.push(text);
  }
  return out;
}

// ---- viewer.js ----

// Showing what the script just made.
//
// Through Thingport's own Three.js rather than a painter of this tool's own: a generator's output runs to a
// hundred thousand triangles and more, which WebGL draws without noticing and a canvas does not.

/** Drag to turn, wheel to come closer. Nothing orbits by itself: a model that spins is harder to look at. */
export function createViewer(host, { library, theme }) {
  let state = null;
  let disposed = false;

  const canvas = document.createElement("canvas");
  host.prepend(canvas);

  const ready = library("three")
    .then((THREE) => {
      if (disposed) return null;
      const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(40, 1, 0.1, 10000);

      scene.add(new THREE.AmbientLight(0xffffff, 1.9));
      const key = new THREE.DirectionalLight(0xffffff, 2.1);
      key.position.set(1, 1.4, 1.2);
      scene.add(key);
      const fill = new THREE.DirectionalLight(0xffffff, 0.7);
      fill.position.set(-1.2, -0.6, -1);
      scene.add(fill);

      const material = new THREE.MeshStandardMaterial({
        color: new THREE.Color(theme.primary),
        roughness: 0.62,
        metalness: 0.03,
        // A generated mesh can have a facet wound the wrong way; showing both sides hides a hole that isn't real.
        side: THREE.DoubleSide,
      });
      const pivot = new THREE.Group();
      scene.add(pivot);

      return { THREE, renderer, scene, camera, material, pivot, mesh: null, distance: 100, angles: { x: 0.9, y: 0.6 } };
    })
    .catch(() => null);

  function draw() {
    if (!state) return;
    const { renderer, scene, camera, pivot, angles, distance } = state;
    // Turned about the upright axis first, then tipped, so dragging sideways spins it rather than rolling it.
    // A positive tilt brings the model's top towards the camera: a plate with lettering on it is otherwise
    // shown from underneath, which looks like a model that came out blank.
    pivot.rotation.order = "YXZ";
    pivot.rotation.set(angles.x, angles.y, 0);
    // A window wider than it is tall sees less up than across, so the model is pushed back by that much.
    camera.position.set(0, 0, distance / Math.min(1, camera.aspect));
    camera.lookAt(0, 0, 0);
    renderer.render(scene, camera);
  }

  function resize() {
    if (!state) return;
    const width = host.clientWidth || 1;
    const height = host.clientHeight || 1;
    state.renderer.setSize(width, height, false);
    state.camera.aspect = width / height;
    state.camera.updateProjectionMatrix();
    draw();
  }

  const observer = new ResizeObserver(resize);
  observer.observe(host);

  let dragging = null;
  canvas.addEventListener("pointerdown", (event) => {
    dragging = { x: event.clientX, y: event.clientY };
    canvas.setPointerCapture(event.pointerId);
  });
  canvas.addEventListener("pointermove", (event) => {
    if (!dragging || !state) return;
    state.angles.y += (event.clientX - dragging.x) * 0.01;
    state.angles.x += (event.clientY - dragging.y) * 0.01;
    dragging = { x: event.clientX, y: event.clientY };
    draw();
  });
  const stop = () => (dragging = null);
  canvas.addEventListener("pointerup", stop);
  canvas.addEventListener("pointercancel", stop);
  canvas.addEventListener(
    "wheel",
    (event) => {
      if (!state) return;
      event.preventDefault();
      state.distance = Math.min(8000, Math.max(5, state.distance * (event.deltaY > 0 ? 1.1 : 0.9)));
      draw();
    },
    { passive: false },
  );

  return {
    /** `mesh` is the geometry the render already parsed: flat vertex and index arrays. */
    async show(mesh) {
      state = await ready;
      if (!state || !mesh) return;
      const { THREE } = state;
      this.clear();

      const indexed = new THREE.BufferGeometry();
      indexed.setAttribute("position", new THREE.BufferAttribute(Float32Array.from(mesh.vertices), 3));
      indexed.setIndex(new THREE.BufferAttribute(Uint32Array.from(mesh.triangles), 1));

      // Each triangle given its own corners before the normals are worked out. A solid shares a vertex between
      // faces that meet at an edge -- a cube's corner belongs to three -- and averaging across them rounds every
      // hard edge off, which on lettering reads as a smeared mess rather than a model.
      const geometry = indexed.toNonIndexed();
      indexed.dispose();
      geometry.computeVertexNormals();
      geometry.computeBoundingSphere();
      geometry.computeBoundingBox();

      // Centred on its own middle, so turning it turns the model rather than swinging it around the origin.
      const middle = new THREE.Vector3();
      geometry.boundingBox.getCenter(middle);
      geometry.translate(-middle.x, -middle.y, -middle.z);

      const object = new THREE.Mesh(geometry, state.material);
      // OpenSCAD has Z up; the camera here looks down -Z, so the model is laid back to stand upright on screen.
      object.rotation.x = -Math.PI / 2;
      state.pivot.add(object);
      state.mesh = object;

      // Far enough back that the whole of it fits the narrower of the two directions, with a little air round it.
      const radius = geometry.boundingSphere?.radius || 10;
      const half = (state.camera.fov * Math.PI) / 360;
      const fit = radius / Math.sin(half);
      state.distance = fit * 1.15;
      state.camera.near = Math.max(0.05, radius / 100);
      state.camera.far = fit * 12;
      resize();
    },
    clear() {
      if (!state?.mesh) return;
      state.pivot.remove(state.mesh);
      state.mesh.geometry.dispose();
      state.mesh = null;
      draw();
    },
    dispose() {
      disposed = true;
      observer.disconnect();
      this.clear();
      state?.renderer.dispose();
      canvas.remove();
    },
  };
}

// ---- ui.js ----

// The customizer's window: the script's own parameters on the left, what they make on the right.
//
// A model generated from a script can be generated again here with other values -- other text, other sizes,
// other options -- and saved back into the library. Nothing is sent anywhere: the engine runs in this tab.


export default async function mount(thingport) {
  const { root, theme, models, ui, t, labels, library, context } = thingport;
  const $ = (id) => root.querySelector(`#osc-${id}`);
  const shell = root.querySelector(".osc");

  for (const [name, value] of Object.entries({
    bg: theme.background,
    panel: theme.paper,
    divider: theme.divider,
    text: theme.text,
    muted: theme.textSecondary,
    accent: theme.primary,
    "accent-ink": theme.primaryContrast ?? "#ffffff",
    danger: theme.error,
    font: theme.fontFamily,
  })) {
    shell.style.setProperty(`--${name}`, value);
  }
  // The side-by-side layout folds when the window is narrow, which it can be without the page being.
  shell.style.containerType = "inline-size";

  const viewer = createViewer($("view"), { library, theme });

  /** What is loaded: the script's text, where it came from, its parameters and the reader's values. */
  let current = null;
  let generated = null;
  let busy = false;

  // ---- loading a script --------------------------------------------------------------------------------------

  async function loadScript({ text: raw, name, from }) {
    setBusy(true, t("busy.reading"));
    try {
      const text = readyScript(raw);
      const openscad = await library("openscad");
      const { parameters } = await openscad.parameters(text);
      current = { text, name, from, parameters, values: defaultValues(parameters) };
      $("name").textContent = name;
      $("where").textContent = from ? t("bar.fromModel", { model: from.name }) : t("bar.fromFile");
      buildForm();
      $("empty").hidden = true;
      enable(true);
      await generate();
    } catch (err) {
      ui.toast(t("error.unreadable", { reason: err.message }), "error");
      setBusy(false);
    }
  }

  async function loadFromModel(model) {
    const related = await models.relatedFiles(model.id);
    const scripts = scriptsAmong(related);
    if (!scripts.length) {
      ui.toast(t("error.noScript", { model: model.name }), "warning");
      return;
    }
    const picker = $("script");
    picker.hidden = scripts.length < 2;
    picker.replaceChildren(
      ...scripts.map((file) => {
        const option = document.createElement("option");
        option.value = file.id;
        option.textContent = file.name;
        return option;
      }),
    );
    const choose = async (fileId) => {
      const file = scripts.find((s) => s.id === fileId) ?? scripts[0];
      const text = await models.relatedText(model.id, file.id);
      await loadScript({ text, name: file.name, from: model });
    };
    picker.onchange = () => void choose(picker.value);
    await choose(scripts[0].id);
  }

  // ---- the form ----------------------------------------------------------------------------------------------

  function buildForm() {
    const side = $("side");
    side.replaceChildren();
    const groups = groupParameters(current.parameters);
    if (!groups.length) {
      const empty = document.createElement("div");
      empty.className = "osc-fields osc-sub";
      empty.textContent = t("form.noParameters");
      side.append(empty);
      return;
    }
    groups.forEach((group, index) => {
      const details = document.createElement("details");
      details.className = "osc-group";
      // The first group open, the rest folded: a script with sixteen groups is otherwise a wall.
      details.open = index === 0 || groups.length <= 3;
      const summary = document.createElement("summary");
      summary.textContent = group.name;
      details.append(summary);
      const fields = document.createElement("div");
      fields.className = "osc-fields";
      for (const parameter of group.parameters) fields.append(fieldFor(parameter));
      details.append(fields);
      side.append(details);
    });
  }

  function fieldFor(parameter) {
    const field = document.createElement("div");
    field.className = "osc-field";

    const label = document.createElement("div");
    label.className = "osc-label";
    const name = document.createElement("span");
    name.className = "osc-name";
    name.textContent = parameter.name;
    label.append(name);

    const shown = document.createElement("span");
    shown.className = "osc-value";
    label.append(shown);

    if (parameter.caption) {
      // Behind a `?` rather than under the control: the explanations are the author's sentences, and a column of
      // them buries the parameters themselves.
      const help = document.createElement("button");
      help.type = "button";
      help.className = "osc-help";
      help.textContent = "?";
      help.title = parameter.caption;
      help.setAttribute("aria-label", parameter.caption);
      label.append(help);
    }
    field.append(label);

    const set = (value) => {
      current.values[parameter.name] = value;
      shown.textContent = typeof value === "boolean" ? "" : String(value);
      $("generate").disabled = busy;
    };
    field.append(controlElement(parameter, set));
    set(current.values[parameter.name]);
    return field;
  }

  function controlElement(parameter, set) {
    const control = controlFor(parameter);
    const value = current.values[parameter.name];

    if (control.kind === "segmented") {
      const group = document.createElement("div");
      group.className = "osc-segmented";
      group.setAttribute("role", "group");
      group.setAttribute("aria-label", parameter.name);
      const buttons = control.options.map((option) => {
        const button = document.createElement("button");
        button.type = "button";
        button.textContent = String(option.name);
        button.title = String(option.name);
        button.setAttribute("aria-pressed", String(option.value === value));
        button.onclick = () => {
          for (const other of buttons) other.setAttribute("aria-pressed", String(other === button));
          set(option.value);
        };
        return button;
      });
      group.append(...buttons);
      return group;
    }

    if (control.kind === "select") {
      const select = document.createElement("select");
      select.setAttribute("aria-label", parameter.name);
      select.replaceChildren(
        ...control.options.map((option) => {
          const element = document.createElement("option");
          element.value = String(option.value);
          element.textContent = String(option.name);
          element.selected = option.value === value;
          return element;
        }),
      );
      select.onchange = () => set(control.options[select.selectedIndex].value);
      return select;
    }

    if (control.kind === "switch") {
      const wrap = document.createElement("label");
      wrap.className = "osc-switch";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.checked = value === true || /^(yes|true|on)$/i.test(String(value));
      const onValue = control.options[0].value;
      const offValue = control.options[1].value;
      input.onchange = () => set(input.checked ? onValue : offValue);
      wrap.append(input, document.createTextNode(parameter.name));
      wrap.querySelector("input").setAttribute("aria-label", parameter.name);
      return wrap;
    }

    if (control.kind === "slider") {
      const input = document.createElement("input");
      input.type = "range";
      input.min = String(control.min);
      input.max = String(control.max);
      input.step = String(control.step);
      input.value = String(value);
      input.setAttribute("aria-label", parameter.name);
      // On input while dragging so the number keeps up; the model is only rendered when asked for.
      input.oninput = () => set(Number(input.value));
      return input;
    }

    const input = document.createElement("input");
    input.type = control.kind === "number" ? "number" : "text";
    if (control.kind === "number") input.step = String(control.step);
    input.value = control.kind === "vector" ? JSON.stringify(value) : String(value);
    input.setAttribute("aria-label", parameter.name);
    input.oninput = () => {
      if (control.kind === "number") set(Number(input.value));
      else if (control.kind === "vector") {
        try {
          set(JSON.parse(input.value));
        } catch {
          // Left as it was until the brackets balance again.
        }
      } else set(input.value);
    };
    return input;
  }

  // ---- generating --------------------------------------------------------------------------------------------

  function setBusy(on, message) {
    busy = on;
    $("busy").hidden = !on;
    if (on && message) $("busy").lastElementChild.textContent = message;
    for (const id of ["generate", "save", "download", "reset", "pick", "open"]) {
      const button = $(id);
      if (button) button.disabled = on || (!current && id !== "pick" && id !== "open");
    }
    if (!on) enable(Boolean(current));
  }

  function enable(on) {
    $("generate").disabled = !on;
    $("reset").disabled = !on;
    $("save").disabled = !on || !generated;
    $("download").disabled = !on || !generated;
  }

  async function generate() {
    if (!current) return;
    setBusy(true, t("busy.generating"));
    $("status").textContent = "";
    $("saved").hidden = true;
    try {
      const openscad = await library("openscad");
      const values = changedValues(current.parameters, current.values);
      const name = generatedName(current.name, current.from?.name, values);
      const result = await openscad.render(current.text, { parameters: values, name });
      generated = { bytes: result.bytes, name };
      viewer.show(result.mesh);
      $("status").textContent = t("status.generated", {
        seconds: result.seconds.toFixed(1),
        size: Math.max(1, Math.round(result.bytes.length / 1024)),
      });
      showNotes(readableWarnings(result.log));
    } catch (err) {
      generated = null;
      viewer.clear();
      showNotes([]);
      $("status").textContent = "";
      ui.toast(t("error.failed"), "error");
      showNotes(String(err.message).split("\n").slice(0, 6));
    } finally {
      setBusy(false);
    }
  }

  function showNotes(lines) {
    const notes = $("notes");
    notes.hidden = !lines.length;
    notes.replaceChildren(
      ...lines.map((line) => {
        const item = document.createElement("li");
        item.textContent = line;
        return item;
      }),
    );
  }

  // ---- saving ------------------------------------------------------------------------------------------------

  async function save() {
    if (!generated) return;
    const file = { name: `${generated.name}.3mf`, data: generated.bytes, type: "model/3mf" };
    setBusy(true, t("busy.saving"));
    try {
      const model = await models.create({
        name: generated.name,
        description: current.from
          ? t("save.description", { model: current.from.name, script: current.name })
          : t("save.descriptionFile", { script: current.name }),
        files: [file],
      });
      ui.toast(t("save.done", { name: model.name }), "success");
      // The toast goes; a button to open what was just saved stays until the next generate.
      const open = $("saved");
      open.hidden = false;
      open.onclick = () => models.open(model.id);
    } catch (err) {
      ui.toast(err.message, "error");
    } finally {
      setBusy(false);
    }
  }

  // ---- the window --------------------------------------------------------------------------------------------

  $("generate").onclick = () => void generate();
  $("save").onclick = () => void save();
  $("reset").onclick = () => {
    if (!current) return;
    current.values = defaultValues(current.parameters);
    buildForm();
    void generate();
  };
  $("download").onclick = () => {
    if (generated) thingport.download({ name: `${generated.name}.3mf`, data: generated.bytes, type: "model/3mf" });
  };
  $("pick").onclick = async () => {
    const model = await pickModel();
    if (model) await loadFromModel(model);
  };
  $("open").onclick = () => {
    const input = document.createElement("input");
    input.type = "file";
    input.accept = ".scad,text/plain";
    input.onchange = async () => {
      const file = input.files?.[0];
      if (file) await loadScript({ text: await file.text(), name: file.name, from: null });
    };
    input.click();
  };

  /**
   * A model to customise.
   *
   * Only the ones that have files beside their plates are offered, which the library's own listing already says,
   * so finding them costs nothing: a script lives beside a model, never as one of its plates.
   */
  async function pickModel() {
    const { models: found } = await models.list({ limit: 200 });
    const candidates = found.filter((model) => model.relatedCount > 0);
    if (!candidates.length) {
      ui.toast(t("error.noneInLibrary"), "info");
      return null;
    }
    return chooseFrom(candidates);
  }

  /** A small list in the window itself; `ui` has a collection picker but none for models. */
  function chooseFrom(candidates) {
    return new Promise((resolve) => {
      const side = $("side");
      const kept = [...side.children];
      side.replaceChildren();

      const panel = document.createElement("div");
      panel.className = "osc-fields";
      const heading = document.createElement("div");
      heading.style.fontWeight = "600";
      heading.textContent = t("pick.title");
      const search = document.createElement("input");
      search.type = "text";
      search.placeholder = t("pick.search");
      search.setAttribute("aria-label", t("pick.search"));
      const list = document.createElement("div");
      list.style.display = "flex";
      list.style.flexDirection = "column";
      list.style.gap = "4px";

      const close = (model) => {
        side.replaceChildren(...kept);
        resolve(model);
      };
      const draw = () => {
        const needle = search.value.trim().toLowerCase();
        const shown = candidates.filter((model) => !needle || model.name.toLowerCase().includes(needle));
        list.replaceChildren(
          ...shown.slice(0, 60).map((model) => {
            const button = document.createElement("button");
            button.className = "osc-btn";
            button.style.textAlign = "left";
            button.textContent = model.name;
            button.onclick = () => close(model);
            return button;
          }),
        );
      };
      search.oninput = draw;
      draw();

      const cancel = document.createElement("button");
      cancel.className = "osc-btn";
      cancel.textContent = t("pick.cancel");
      cancel.onclick = () => close(null);

      panel.append(heading, search, list, cancel);
      side.append(panel);
      search.focus();
    });
  }

  labels();
  enable(false);

  // Opened from a model's own menu rather than from the Tools page: that model's script is what to open.
  if (context?.modelId) {
    try {
      await loadFromModel(await models.get(context.modelId));
    } catch (err) {
      ui.toast(t("error.unreadable", { reason: err.message }), "error");
    }
  }

  return () => viewer.dispose();
}
